/** 业务异常基类，携带HTTP状态码。 */
abstract class ApiException extends RuntimeException {

    private final HttpStatus status;

    ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    HttpStatus status() {
        return status;
    }
}

/** 资源不存在，404。 */
