    BusinessException(String message) {
        super(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

/** 请求参数非法，400。 */
final class BadRequestException extends ApiException {

    BadRequestException(String message) {
        super(HttpStatus.BAD_REQUEST, message);
    }
}
